// Frida hook script: intercept Cocos2d-x camera/projection calls
// Usage: frida -U -n "moe.low.arc" -l hook_camera.js

"use strict";

const LIB = "libcocos2dcpp.so";

function hookBySymbol(symbolName, callbacks) {
    const addr = Module.findExportByName(LIB, symbolName);
    if (addr) {
        Interceptor.attach(addr, callbacks);
        console.log(`[+] Hooked ${symbolName} at ${addr}`);
    } else {
        console.log(`[-] Symbol not found: ${symbolName}`);
    }
}

// Hook Mat4::createPerspective to capture FOV, aspect, near, far
// Signature: static void createPerspective(float fov, float aspect, float near, float far, Mat4* dst)
hookBySymbol("_ZN7cocos2d4Mat417createPerspectiveEffffPS0_", {
    onEnter: function (args) {
        const fov = args[0].toFloat ? args[0].toFloat() : 0;
        const aspect = args[1].toFloat ? args[1].toFloat() : 0;
        const near = args[2].toFloat ? args[2].toFloat() : 0;
        const far = args[3].toFloat ? args[3].toFloat() : 0;
        console.log(`[Camera] createPerspective: fov=${fov}, aspect=${aspect}, near=${near}, far=${far}`);
    }
});

// Hook Camera::setPosition3D to capture camera position
hookBySymbol("_ZN7cocos2d6Camera13setPosition3DERKNS_4Vec3E", {
    onEnter: function (args) {
        const vec3Ptr = args[1];
        const x = vec3Ptr.readFloat();
        const y = vec3Ptr.add(4).readFloat();
        const z = vec3Ptr.add(8).readFloat();
        console.log(`[Camera] setPosition3D: x=${x}, y=${y}, z=${z}`);
    }
});

// Hook Camera::lookAt to capture look-at target and up vector
hookBySymbol("_ZN7cocos2d6Camera6lookAtERKNS_4Vec3ES3_", {
    onEnter: function (args) {
        const target = args[1];
        const up = args[2];
        const tx = target.readFloat();
        const ty = target.add(4).readFloat();
        const tz = target.add(8).readFloat();
        const ux = up.readFloat();
        const uy = up.add(4).readFloat();
        const uz = up.add(8).readFloat();
        console.log(`[Camera] lookAt: target=(${tx}, ${ty}, ${tz}), up=(${ux}, ${uy}, ${uz})`);
    }
});

console.log("[*] Arcaea camera hooks loaded. Play a chart to trigger captures.");

