// Ghidra Java script: export gameplay-relevant xrefs
// @category Analysis

import ghidra.app.script.GhidraScript;
import ghidra.program.model.listing.*;
import ghidra.program.model.symbol.*;
import ghidra.program.model.address.*;
import ghidra.program.model.data.*;
import java.io.*;
import java.util.*;

public class GhidraExport extends GhidraScript {

    private PrintWriter pw;

    @Override
    public void run() throws Exception {
        File outFile = new File("f:/Code/better-arc/re/notes/ghidra-export.md");
        pw = new PrintWriter(new FileWriter(outFile));
        w("# Ghidra Auto-Export — Arcaea 6.13.10c\n");

        String[] searchStrings = {
            "TimingPointDensityFactor",
            "highspeed",
            "track_width",
            "createPerspective",
            "createLookAt",
            "enwidenlanes",
            "AudioOffset",
            "fovy=60",
            "z_clip",
            "track_custom_mask_shader",
        };

        w("## Key String Cross-References\n");

        Listing listing = currentProgram.getListing();
        ReferenceManager refMgr = currentProgram.getReferenceManager();
        FunctionManager fm = currentProgram.getFunctionManager();

        DataIterator dataIter = listing.getDefinedData(true);
        int count = 0;
        while (dataIter.hasNext() && count < 2000000) {
            Data data = dataIter.next();
            count++;
            if (!data.hasStringValue()) continue;
            Object val = data.getValue();
            if (val == null) continue;
            String s = val.toString();

            for (String search : searchStrings) {
                if (s.contains(search)) {
                    w("### \"" + search + "\"");
                    w("- String at `" + data.getAddress() + "`: `" + truncate(s, 120) + "`");

                    Reference[] refs = refMgr.getReferencesTo(data.getAddress());
                    if (refs.length == 0) {
                        w("  - No direct xrefs");
                    }
                    for (Reference ref : refs) {
                        Address fromAddr = ref.getFromAddress();
                        Function func = fm.getFunctionContaining(fromAddr);
                        String funcName = func != null ? func.getName() : "???";
                        String funcAddr = func != null ? func.getEntryPoint().toString() : "???";
                        w("  - xref from `" + fromAddr + "` in **`" + funcName + "`** @ `" + funcAddr + "`");
                    }
                    w("");
                }
            }
        }
        w("(Scanned " + count + " data items)\n");

        // Find gameplay functions by demangled name
        w("## Gameplay Functions (by demangled name)\n");

        String[] classPatterns = {
            "GameModel", "GameScene", "GameTimeline",
            "CameraController", "TrackBase", "TrackLayer",
            "LogicChart", "LogicNote", "LogicTapNote", "LogicHoldNote",
            "LogicArcNote", "LogicArcTapNote", "LogicFlickNote",
            "LogicTimingEvent", "LogicSceneControl", "LogicCameraControl",
            "RenderNote", "RenderTapNote", "RenderHoldNote",
            "RenderArcNote", "RenderArcTapNote", "RenderFlickNote",
            "NotePosition", "ArcSegment",
            "NoteBurstRenderer", "GameSceneVisualControl",
            "ScoreState", "HighspeedSetting",
        };

        FunctionIterator funcIter = fm.getFunctions(true);
        List<String> gameFuncs = new ArrayList<>();
        while (funcIter.hasNext()) {
            Function func = funcIter.next();
            String name = func.getName();
            for (String pat : classPatterns) {
                if (name.contains(pat)) {
                    gameFuncs.add("`" + func.getEntryPoint() + "` — " + name);
                    break;
                }
            }
        }
        Collections.sort(gameFuncs);
        for (String line : gameFuncs) {
            w("- " + line);
        }

        // Summary stats
        w("\n## Stats\n");
        int totalFuncs = 0;
        funcIter = fm.getFunctions(true);
        while (funcIter.hasNext()) { funcIter.next(); totalFuncs++; }
        w("- Total functions identified: " + totalFuncs);
        w("- Gameplay-related functions: " + gameFuncs.size());
        w("- Data items scanned: " + count);

        w("\n---\nExport complete.");
        pw.close();
        println("Export written to: " + outFile.getAbsolutePath());
    }

    private void w(String s) {
        pw.println(s);
        println(s);
    }

    private String truncate(String s, int max) {
        s = s.replace("\n", " ").replace("\r", "");
        return s.length() > max ? s.substring(0, max) + "..." : s;
    }
}

