// Find all callers of createPerspective, and decompile them + their callers
// @category Analysis

import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.address.*;
import ghidra.program.model.symbol.*;
import java.io.*;
import java.util.*;

public class FindCallers extends GhidraScript {

    private DecompInterface decomp;
    private PrintWriter pw;
    private FunctionManager fm;

    @Override
    public void run() throws Exception {
        File outFile = new File("f:/Code/better-arc/re/notes/callers-analysis.md");
        pw = new PrintWriter(new FileWriter(outFile));
        fm = currentProgram.getFunctionManager();
        ReferenceManager refMgr = currentProgram.getReferenceManager();

        decomp = new DecompInterface();
        decomp.openProgram(currentProgram);

        pw.println("# Caller Analysis — Key Functions\n");

        // 1. Find all callers of Mat4::createPerspective (FUN_010e7a70)
        pw.println("## Callers of createPerspective (FUN_010e7a70)\n");
        findCallersAndDecompile("010e7a70");

        // 2. Find all callers of createLookAt (FUN_015ad49c)
        pw.println("\n## Callers of createLookAt (FUN_015ad49c)\n");
        findCallersAndDecompile("015ad49c");

        // 3. Decompile the highspeed reader more carefully
        pw.println("\n## highspeed reader (FUN_009d91e8) — full decompile\n");
        decompileAddr("009d91e8");

        // 4. Track mask shader setup (FUN_00fec560) — has track_width
        pw.println("\n## Track mask shader setup (FUN_00fec560)\n");
        decompileAddr("00fec560");

        // 5. enwidenlanes handler
        pw.println("\n## enwidenlanes handler (FUN_011c46f0)\n");
        decompileAddr("011c46f0");

        decomp.dispose();
        pw.close();
        println("Output written to: " + outFile.getAbsolutePath());
    }

    private void findCallersAndDecompile(String targetAddr) throws Exception {
        Address addr = toAddr(targetAddr);
        Function targetFunc = fm.getFunctionAt(addr);
        if (targetFunc == null) {
            pw.println("Target function not found at " + targetAddr);
            return;
        }

        pw.println("Target: `" + targetFunc.getName() + "` @ `" + targetAddr + "`\n");

        // Find all references to this function
        ReferenceIterator refs = currentProgram.getReferenceManager().getReferencesTo(addr);
        Set<String> callerAddrs = new LinkedHashSet<>();
        while (refs.hasNext()) {
            Reference ref = refs.next();
            if (ref.getReferenceType().isCall() || ref.getReferenceType().isFlow()) {
                Function caller = fm.getFunctionContaining(ref.getFromAddress());
                if (caller != null) {
                    callerAddrs.add(caller.getEntryPoint().toString());
                }
            }
        }

        pw.println("Found " + callerAddrs.size() + " callers:\n");

        for (String callerAddr : callerAddrs) {
            decompileAddr(callerAddr);
        }
    }

    private void decompileAddr(String addrStr) throws Exception {
        Address addr = toAddr(addrStr);
        Function func = fm.getFunctionAt(addr);
        if (func == null) {
            func = fm.getFunctionContaining(addr);
        }
        if (func == null) {
            pw.println("No function at/containing " + addrStr + "\n---\n");
            return;
        }

        pw.println("### `" + func.getName() + "` @ `" + func.getEntryPoint() + "`");
        pw.println("Size: " + func.getBody().getNumAddresses() + " bytes\n");

        DecompileResults results = decomp.decompileFunction(func, 60, monitor);
        if (results.decompileCompleted() && results.getDecompiledFunction() != null) {
            String code = results.getDecompiledFunction().getC();
            // Truncate very large functions
            if (code.length() > 8000) {
                code = code.substring(0, 8000) + "\n\n// ... truncated (function too large) ...\n";
            }
            pw.println("```c");
            pw.println(code);
            pw.println("```\n---\n");
        } else {
            pw.println("*Decompilation failed*\n---\n");
        }
    }
}

