// Deep dive: decompile TimingPointDensityFactor handler internals,
// find track_width callers, and search for judgment window constants
// @category Analysis

import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.address.*;
import ghidra.program.model.symbol.*;
import java.io.*;
import java.util.*;

public class DeepDive extends GhidraScript {

    private DecompInterface decomp;
    private PrintWriter pw;
    private FunctionManager fm;
    private ReferenceManager refMgr;

    @Override
    public void run() throws Exception {
        File outFile = new File("f:/Code/better-arc/re/notes/deep-dive.md");
        pw = new PrintWriter(new FileWriter(outFile));
        fm = currentProgram.getFunctionManager();
        refMgr = currentProgram.getReferenceManager();

        decomp = new DecompInterface();
        decomp.openProgram(currentProgram);

        pw.println("# Deep Dive Analysis\n");

        // 1. Find callers of track_width shader setup (FUN_00fec560)
        pw.println("## Callers of track shader setup (FUN_00fec560)\n");
        pw.println("This will reveal the actual track_width value.\n");
        findCallersAndDecompile("00fec560");

        // 2. Find what calls the TimingPointDensityFactor handler
        // FUN_00ab0038 is too large — look for functions that use its output
        // Let's search for functions that reference floorposition or note position calculation
        pw.println("\n## Functions referencing NotePosition / position calculation\n");

        // Search for string "floorposition" or similar
        searchStringAndDecompileRefs("FloorPosition");
        searchStringAndDecompileRefs("floorPosition");

        // 3. Search for judgment-related constants
        // Common windows: 25ms pure, 100ms far, 150ms lost
        pw.println("\n## Judgment-related string search\n");
        searchStringAndDecompileRefs("judge");
        searchStringAndDecompileRefs("Judge");
        searchStringAndDecompileRefs("PURE");
        searchStringAndDecompileRefs("shinyPerfect");
        searchStringAndDecompileRefs("inputLocked");

        // 4. Find what references the Note/Render classes for scaling
        pw.println("\n## Note scaling: search for note.png texture loading\n");
        searchStringAndDecompileRefs("note.png");

        decomp.dispose();
        pw.close();
        println("Output written to: " + outFile.getAbsolutePath());
    }

    private void searchStringAndDecompileRefs(String search) throws Exception {
        pw.println("### Search: \"" + search + "\"\n");

        Listing listing = currentProgram.getListing();
        DataIterator dataIter = listing.getDefinedData(true);
        int count = 0;
        boolean found = false;

        while (dataIter.hasNext() && count < 2000000) {
            Data data = dataIter.next();
            count++;
            if (!data.hasStringValue()) continue;
            Object val = data.getValue();
            if (val == null) continue;
            String s = val.toString();
            if (!s.contains(search)) continue;

            found = true;
            pw.println("String: `" + truncate(s, 80) + "` @ `" + data.getAddress() + "`");

            ReferenceIterator refs = refMgr.getReferencesTo(data.getAddress());
            while (refs.hasNext()) {
                Reference ref = refs.next();
                Address fromAddr = ref.getFromAddress();
                Function func = fm.getFunctionContaining(fromAddr);
                if (func != null) {
                    pw.println("  -> `" + func.getName() + "` @ `" + func.getEntryPoint() + "`");
                }
            }
            pw.println("");
        }

        if (!found) {
            pw.println("*No strings found*\n");
        }
    }

    private void findCallersAndDecompile(String targetAddr) throws Exception {
        Address addr = toAddr(targetAddr);
        Function targetFunc = fm.getFunctionAt(addr);
        if (targetFunc == null) {
            pw.println("Function not found at " + targetAddr + "\n");
            return;
        }

        ReferenceIterator refs = refMgr.getReferencesTo(addr);
        Set<String> callerAddrs = new LinkedHashSet<>();
        while (refs.hasNext()) {
            Reference ref = refs.next();
            Function caller = fm.getFunctionContaining(ref.getFromAddress());
            if (caller != null && !caller.getEntryPoint().toString().equals(targetAddr)) {
                callerAddrs.add(caller.getEntryPoint().toString());
            }
        }

        pw.println("Found " + callerAddrs.size() + " callers\n");

        for (String ca : callerAddrs) {
            decompileAddr(ca, 6000);
        }
    }

    private void decompileAddr(String addrStr, int maxLen) throws Exception {
        Address addr = toAddr(addrStr);
        Function func = fm.getFunctionAt(addr);
        if (func == null) func = fm.getFunctionContaining(addr);
        if (func == null) return;

        pw.println("### `" + func.getName() + "` @ `" + func.getEntryPoint() + "` (" + func.getBody().getNumAddresses() + " bytes)\n");

        DecompileResults results = decomp.decompileFunction(func, 60, monitor);
        if (results.decompileCompleted() && results.getDecompiledFunction() != null) {
            String code = results.getDecompiledFunction().getC();
            if (code.length() > maxLen) {
                code = code.substring(0, maxLen) + "\n// ... truncated ...\n";
            }
            pw.println("```c");
            pw.println(code);
            pw.println("```\n---\n");
        } else {
            pw.println("*Decompilation failed*\n---\n");
        }
    }

    private String truncate(String s, int max) {
        s = s.replace("\n", " ").replace("\r", "");
        return s.length() > max ? s.substring(0, max) + "..." : s;
    }
}

