// @category Analysis

import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.address.*;
import ghidra.program.model.symbol.*;
import java.io.*;
import java.util.*;

public class FinalDive extends GhidraScript {

    private DecompInterface decomp;
    private PrintWriter pw;
    private FunctionManager fm;

    @Override
    public void run() throws Exception {
        File outFile = new File("f:/Code/better-arc/re/notes/final-dive.md");
        pw = new PrintWriter(new FileWriter(outFile));
        fm = currentProgram.getFunctionManager();

        decomp = new DecompInterface();
        decomp.openProgram(currentProgram);

        pw.println("# Final Dive — Note, Judgment, Track\n");

        // 1. Note texture loader — may contain scale/size constants
        pw.println("## Note texture loader (FUN_00879740)\n");
        decompileAddr("00879740", 10000);

        // 2. Judgment string handler — may have judgment windows
        pw.println("\n## Judgment handler (FUN_00c0f4e0) — references 'judgement'\n");
        decompileAddr("00c0f4e0", 10000);

        // 3. The large track builder — search for FUN_00fec560 call within it
        // Instead, let's search for float constants that represent common track widths
        // Arcaea community sources suggest track width around 5.0-6.0 or similar

        // 4. Search for the judgment engine — likely in GameModel
        // Look for functions near the touch handler area
        pw.println("\n## GameModel touch handler area\n");
        // GameModel::initializeTouchEvents is at one of the lambda addresses
        // The lambdas are the actual judgment code
        // Search for "near" (Far judgment grade) as a string
        searchAndDecompile("nearCount");

        // 5. Score calculation
        pw.println("\n## Score calculation reference\n");
        searchAndDecompile("perfect_count");

        decomp.dispose();
        pw.close();
        println("Output written to: " + outFile.getAbsolutePath());
    }

    private void searchAndDecompile(String search) throws Exception {
        pw.println("### Search: \"" + search + "\"\n");
        Listing listing = currentProgram.getListing();
        DataIterator dataIter = listing.getDefinedData(true);
        int count = 0;

        while (dataIter.hasNext() && count < 2000000) {
            Data data = dataIter.next();
            count++;
            if (!data.hasStringValue()) continue;
            Object val = data.getValue();
            if (val == null) continue;
            String s = val.toString();
            if (!s.equals(search)) continue;

            pw.println("Exact match: `" + s + "` @ `" + data.getAddress() + "`\n");

            ReferenceIterator refs = currentProgram.getReferenceManager().getReferencesTo(data.getAddress());
            while (refs.hasNext()) {
                Reference ref = refs.next();
                Function func = fm.getFunctionContaining(ref.getFromAddress());
                if (func != null) {
                    pw.println("Referenced in `" + func.getName() + "` @ `" + func.getEntryPoint() + "`");
                    decompileAddr(func.getEntryPoint().toString(), 4000);
                }
            }
        }
    }

    private void decompileAddr(String addrStr, int maxLen) throws Exception {
        Address addr = toAddr(addrStr);
        Function func = fm.getFunctionAt(addr);
        if (func == null) func = fm.getFunctionContaining(addr);
        if (func == null) {
            pw.println("No function at " + addrStr + "\n---\n");
            return;
        }

        pw.println("#### `" + func.getName() + "` @ `" + func.getEntryPoint() + "` (" + func.getBody().getNumAddresses() + " bytes)\n");

        DecompileResults results = decomp.decompileFunction(func, 120, monitor);
        if (results.decompileCompleted() && results.getDecompiledFunction() != null) {
            String code = results.getDecompiledFunction().getC();
            if (code.length() > maxLen) {
                code = code.substring(0, maxLen) + "\n// ... truncated ...\n";
            }
            pw.println("```c");
            pw.println(code);
            pw.println("```\n---\n");
        } else {
            pw.println("*Decompilation failed*\n---\n");
        }
    }
}

