"use strict";

// Hook Arcaea gameplay functions to capture rendering parameters
// Usage: frida -U -n "moe.low.arc" -l hook_gameplay.js

const LIB = "libcocos2dcpp.so";

function waitForLib(callback) {
    const m = Module.findBaseAddress(LIB);
    if (m) {
        callback(m);
        return;
    }
    console.log("[-] " + LIB + " not loaded yet. Attach after game is running.");
}

waitForLib(function (base) {
    console.log("[+] " + LIB + " base: " + base);

    // =============================================
    // 1. createPerspective (FUN_010e7a70)
    //    Signature: createPerspective(float fov, float aspect, float near, float far, Mat4* dst)
    // =============================================
    const createPerspective = base.add(0x010e7a70);
    Interceptor.attach(createPerspective, {
        onEnter: function (args) {
            // ARM64: float args in s0-s3, pointer in x0-x7
            // But this is a C++ function so params might be in different regs
            // Actually for ARM64, first 8 float args go in s0-s7
            // arg[0] = fov (float, but frida passes as NativePointer from register)
            // We need to read float registers
            // In Frida, for ARM64: args[0..7] are x0..x7 (integer regs)
            // Float args are in SIMD regs, need special handling
            console.log("[createPerspective] called from " + this.returnAddress.sub(base));
        }
    });

    // =============================================
    // 2. Camera setup: FUN_00bfefb0
    //    Main 3D projection setup — stores FOV, aspect, near, far
    // =============================================
    const cameraSetup = base.add(0x00bfefb0);
    Interceptor.attach(cameraSetup, {
        onEnter: function (args) {
            this.param1 = args[0]; // "this" pointer (Camera object)
            console.log("[CameraSetup] entered, this=" + args[0]);
        },
        onLeave: function (retval) {
            const p = this.param1;
            // Read stored values from the Camera object
            // offset 0x7f*8 = 0x3F8: FOV
            // offset 0x81*8 = 0x408: near
            // But these are in units of long (8 bytes), so:
            // param_1 + 0x7f (long array index) => byte offset 0x7f*8 = 0x3F8
            // *(undefined4 *)(param_1 + 0x7f) = 0x42700000 -> but this is long* arithmetic
            // In decompiled code param_1 is long*, so +0x7f means +0x7f*8 = +0x3F8 bytes
            const fov = p.add(0x3F8).readFloat();
            const aspect = p.add(0x404).readFloat();
            const near = p.add(0x408).readFloat();
            const far = p.add(0x40c).readFloat();
            console.log("[CameraSetup] FOV=" + fov + " aspect=" + aspect + " near=" + near + " far=" + far);
        }
    });

    // =============================================
    // 3. Track mask shader setup: FUN_00fec560
    //    Params: (texture_height, ?, ?, ?, trackNode*, textureMask, mask_inverse)
    //    Inside it sets: z_clip, texture_height, track_width, fixed_x_pos, model_width
    // =============================================
    const trackShaderSetup = base.add(0x00fec560);
    Interceptor.attach(trackShaderSetup, {
        onEnter: function (args) {
            // float params are in s0-s3 on ARM64
