            // param_5 (long*) = x0, param_6 = x1, param_7 (uint) = w2
            console.log("[TrackShader] param5(trackNode)=" + args[0] +
                       " param6(texture)=" + args[1] +
                       " param7(mask_inverse)=" + args[2]);

