// Search heap for perspective projection matrices
// A perspective matrix has a specific structure:
// [m00  0    0    0  ]
// [0    m11  0    0  ]
// [0    0    m22  -1 ]
// [0    0    m32   0 ]
// 
// We search for -1.0 (0xBF800000) at the m23 position
// and verify m00, m11 > 0 and other elements are 0

var ranges = Process.enumerateRanges('rw-');
console.log('=== Searching for perspective projection matrices ===');
var negOnePattern = '00 00 80 BF'; // -1.0f
var count = 0;

ranges.forEach(function(r) {
    if (r.size > 2*1024*1024) return; // skip very large
    try {
        var matches = Memory.scanSync(r.base, r.size, negOnePattern);
        matches.forEach(function(m) {
            // m23=-1 is at matrix offset [2][3] = index 11 = byte offset 44
            // So matrix starts at m.address - 44
            var matBase = m.address.sub(44);
            try {
                var m00 = matBase.readFloat();
                var m01 = matBase.add(4).readFloat();
                var m10 = matBase.add(16).readFloat();
                var m11 = matBase.add(20).readFloat();
                var m22 = matBase.add(40).readFloat();
                var m23 = matBase.add(44).readFloat(); // should be -1
                var m30 = matBase.add(48).readFloat();
                var m31 = matBase.add(52).readFloat();
                var m32 = matBase.add(56).readFloat();
                var m33 = matBase.add(60).readFloat();

                // Check perspective matrix pattern
                if (m00 > 0.1 && m00 < 10 &&
                    m11 > 0.1 && m11 < 10 &&
                    Math.abs(m01) < 0.001 &&
                    Math.abs(m10) < 0.001 &&
                    Math.abs(m23 + 1.0) < 0.001 &&
                    Math.abs(m30) < 0.001 &&
                    Math.abs(m31) < 0.001 &&
                    Math.abs(m33) < 0.001 &&
                    m32 < 0) {
                    count++;
                    var aspect = m11 / m00;
                    var near_p = m32 / (m22 - 1.0);
                    var far_p = m32 / (m22 + 1.0);
                    var fov = 2.0 * Math.atan(1.0 / m11) * 180.0 / Math.PI;
                    console.log('\\n[Matrix #' + count + '] @ ' + matBase);
                    console.log('  FOV    = ' + fov.toFixed(2) + ' deg');
                    console.log('  aspect = ' + aspect.toFixed(6));
                    console.log('  near   = ' + near_p.toFixed(4));
                    console.log('  far    = ' + far_p.toFixed(4));
                    console.log('  m00=' + m00.toFixed(6) + ' m11=' + m11.toFixed(6));
                    console.log('  m22=' + m22.toFixed(6) + ' m32=' + m32.toFixed(6));
                }
            } catch(e2) {}
        });
    } catch(e) {}
});
console.log('\\nTotal: ' + count + ' perspective matrices found');
